# Generated by aebench-writer/v1 from `benford-world-bank-population` (`sha256:fc60ba6eba430027db54b090493dbde4cb10e018c457d4a871d440e6b1d8590e`)
"""Shared helpers for the generated AEBench oracle (aebench-writer/v1 §6, §7).

Extraction and comparison (§6.2, §6.3) have no AEBench dependency so the writer itself can import
this module to compute reference values; the check builders import AEBench lazily.
"""
from __future__ import annotations

import csv
import hashlib
import json
import math
import os
import re
import shutil
import time
from pathlib import Path
from typing import Any, Callable

DROP_SUBSTRINGS = ("path", "dir", "file", "time", "date", "host", "user", "version", "duration",
                   "elapsed", "seconds")
HASH_RE = re.compile(r"^[0-9a-f]{32,128}$")
INT_RE = re.compile(r"^[+-]?\d+$")
FLOAT_RE = re.compile(r"^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$")
CHECKS_LOG = "aebench-writer-checks.jsonl"
SCRATCH_DIR = "aebench-writer-scratch"
DEFAULT_CHECK_TIMEOUT_S = 600.0


# ----------------------------------------------------------------------------- extraction (§6.2)
def _pointer_token(key: str) -> str:
    return key.replace("~", "~0").replace("/", "~1")


def _json_leaves(node: Any, pointer: str, out: list[tuple[str, Any, bool]]) -> None:
    if isinstance(node, dict):
        for k, v in node.items():
            _json_leaves(v, f"{pointer}/{_pointer_token(str(k))}", out)
    elif isinstance(node, list):
        for i, v in enumerate(node):
            _json_leaves(v, f"{pointer}/{i}", out)
    else:
        out.append((pointer, node, isinstance(node, int) and not isinstance(node, bool)))


def _csv_leaves(text: str) -> list[tuple[str, Any, bool]]:
    rows = list(csv.reader(text.splitlines()))
    if not rows:
        return []
    header = rows[0]
    out: list[tuple[str, Any, bool]] = []
    seen: set[str] = set()
    for row in rows[1:]:
        if not row:
            continue
        first = row[0]
        if first in seen:
            continue
        seen.add(first)
        for col_index in range(1, min(len(row), len(header))):
            cell = row[col_index]
            key = f"{first}/{header[col_index]}"
            s = cell.strip()
            if INT_RE.match(s):
                out.append((key, int(s), True))
            elif FLOAT_RE.match(s):
                out.append((key, float(s), False))
            else:
                out.append((key, cell, False))
    return out


def leaves(path: str | Path, fmt: str) -> list[tuple[str, Any, bool]]:
    """All leaves of a JSON or CSV file as (key, value, is_integer). Raises ValueError."""
    data = Path(path).read_bytes()
    try:
        text = data.decode("utf-8-sig")
    except UnicodeDecodeError as exc:
        raise ValueError(f"not UTF-8: {exc}") from exc
    if fmt == "json":
        try:
            doc = json.loads(text)
        except json.JSONDecodeError as exc:
            raise ValueError(f"invalid JSON: {exc}") from exc
        out: list[tuple[str, Any, bool]] = []
        _json_leaves(doc, "", out)
        return out
    if fmt == "csv":
        return _csv_leaves(text)
    raise ValueError(f"unsupported format {fmt!r}")


def key_dropped(key: str) -> bool:
    low = key.lower()
    return any(s in low for s in DROP_SUBSTRINGS)


def volatile_regex(pattern: str) -> re.Pattern:
    """SPEC §2.3: `*` = any chars except `/`, `**` = any chars, everything else literal; whole key."""
    out, i = [], 0
    while i < len(pattern):
        if pattern.startswith("**", i):
            out.append(".*")
            i += 2
        elif pattern[i] == "*":
            out.append("[^/]*")
            i += 1
        else:
            out.append(re.escape(pattern[i]))
            i += 1
    return re.compile("".join(out), re.DOTALL)


def classify(key: str, value: Any, is_int: bool) -> str | None:
    """'exact', 'float', or None (not a comparable value) for one leaf (§6.2)."""
    if value is None:
        return None
    if isinstance(value, bool):
        return "exact"
    if isinstance(value, (int, float)):
        return "exact" if is_int else "float"
    if isinstance(value, str) and HASH_RE.match(value):
        return "exact"
    return None


def extract(path: str | Path, fmt: str, volatile: list[str] | None = None
            ) -> tuple[dict[str, tuple[Any, str]], list[tuple[str, str]]]:
    """Kept leaves {key: (value, 'exact'|'float')} and the dropped keys with their reason
    ('name rule' or 'volatile') (§6.2). Non-comparable values (other strings, null) are skipped
    silently."""
    pats = [volatile_regex(v) for v in (volatile or [])]
    kept: dict[str, tuple[Any, str]] = {}
    dropped: list[tuple[str, str]] = []
    seen: set[str] = set()
    for key, value, is_int in leaves(path, fmt):
        if key in seen:
            continue
        seen.add(key)
        if key_dropped(key):
            dropped.append((key, "name rule"))
            continue
        if any(p.fullmatch(key) for p in pats):
            dropped.append((key, "volatile"))
            continue
        rule = classify(key, value, is_int)
        if rule is not None:
            kept[key] = (value, rule)
    return kept, dropped


def observed_values(path: str | Path, fmt: str) -> dict[str, Any]:
    out: dict[str, Any] = {}
    for key, value, _ in leaves(path, fmt):
        out.setdefault(key, value)
    return out


# ----------------------------------------------------------------------------- comparison (§6.3)
def _is_number(v: Any) -> bool:
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def value_matches(observed: Any, spec: dict) -> bool:
    ref = spec["value"]
    if spec["rule"] == "exact":
        if isinstance(ref, bool) or isinstance(observed, bool):
            return isinstance(ref, bool) and isinstance(observed, bool) and ref == observed
        if isinstance(ref, str):
            return observed == ref
        return _is_number(observed) and observed == ref
    if not _is_number(observed) or not _is_number(ref):
        return False
    if math.isnan(ref) or math.isnan(observed):
        return math.isnan(ref) and math.isnan(observed)
    if "rel_tol" in spec or "abs_tol" in spec:
        bound = max(float(spec.get("rel_tol") or 0) * abs(ref), float(spec.get("abs_tol") or 0))
    else:
        bound = float(spec["tolerance"]) * max(1.0, abs(ref))
    return abs(observed - ref) <= bound


def compare(observed: dict[str, Any], reference: dict[str, dict]) -> list[str]:
    """Mismatch lines `<key>: observed <x>, reference <y>`; missing keys fail, extra keys ignored."""
    mismatches: list[str] = []
    for key, spec in reference.items():
        if key not in observed:
            mismatches.append(f"{key}: observed (missing), reference {json.dumps(spec['value'])}")
        elif not value_matches(observed[key], spec):
            mismatches.append(f"{key}: observed {json.dumps(observed[key])}, "
                              f"reference {json.dumps(spec['value'])}")
    return mismatches


def parse_runtime(value: Any) -> float | None:
    """Seconds for `expected_runtime` (§7.4): a number, or `<number><s|m|h|d>`; None if unparsable."""
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        m = re.fullmatch(r"\s*(\d+(?:\.\d+)?)\s*([smhd])\s*", value)
        if m:
            return float(m.group(1)) * {"s": 1, "m": 60, "h": 3600, "d": 86400}[m.group(2)]
    return None


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        for chunk in iter(lambda: fh.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


# ----------------------------------------------------------------------------- check plumbing
def _result_types():
    from evaluator.oracles.reporting import Check, CheckResult
    return Check, CheckResult


def logged_check(oracle, phase: str, name: str, fn: Callable[[], tuple[bool, str]],
                 optional: bool = False):
    """A check whose outcome is also appended to `aebench-writer-checks.jsonl` (§7.4)."""
    Check, CheckResult = _result_types()

    def run(_executor):
        try:
            ok, message = fn()
        except Exception as exc:  # noqa: BLE001 - a broken check is a failed check
            ok, message = False, f"unexpected error: {type(exc).__name__}: {exc}"
        log = oracle.output_path(CHECKS_LOG)
        log.parent.mkdir(parents=True, exist_ok=True)
        with open(log, "a", encoding="utf-8") as fh:
            fh.write(json.dumps({"phase": phase, "check": name, "ok": ok, "message": message},
                                sort_keys=True) + "\n")
        return CheckResult.success(message) if ok else CheckResult.failure(message)

    return Check(name=name, optional=optional, fn=run)


def artifact_root(oracle, config: dict) -> Path:
    sub = config.get("artifact_subdir") or ""
    return oracle.workspace_path(sub) if sub else oracle.workspace_path()


def _tail(text: str, n: int = 600) -> str:
    text = (text or "").strip()
    return text if len(text) <= n else "…" + text[-n:]


def _run(oracle, cmd: str, cwd: Path, env: dict | None, timeout: float) -> tuple[bool, str]:
    res = oracle.run_command(cmd=cmd, cwd=cwd, env=env or None, timeout_seconds=max(timeout, 1.0),
                             use_shell=True)
    if res.timed_out:
        return False, f"timed out after {timeout:.0f}s: {cmd}"
    if res.returncode != 0:
        return False, (f"exit {res.returncode}: {cmd}\nstdout: {_tail(res.stdout)}\n"
                       f"stderr: {_tail(res.stderr)}")
    return True, f"exit 0: {cmd}"


# ----------------------------------------------------------------------------- env_setup (§7.1)
def env_setup_checks(oracle, config: dict) -> list:
    phase = "env_setup"

    def python_version() -> tuple[bool, str]:
        res = oracle.run_command(cmd=["python3", "--version"], timeout_seconds=60)
        text = f"{res.stdout} {res.stderr}"
        m = re.search(r"(\d+)\.(\d+)(?:\.(\d+))?", text)
        if res.returncode != 0 or not m:
            return False, f"python3 not runnable: {_tail(text)}"
        v = (int(m.group(1)), int(m.group(2)), int(m.group(3) or 0))
        ok = v >= (3, 10, 0)
        return ok, f"python3 {'.'.join(map(str, v))} ({'>=' if ok else '<'} 3.10)"

    checks = [logged_check(oracle, phase, "env:python3_version", python_version)]
    for env in config.get("environments", []):
        digest = env["digest"]
        checks.append(logged_check(
            oracle, phase, f"environment:{env['name']}:image_digest",
            lambda d=digest: (True, f"artifact pins image {d}; AEBench runs in its own image"),
            optional=True))
    instr = config["instructions_path"]

    def instructions() -> tuple[bool, str]:
        p = oracle.workspace_path(instr)
        return p.is_file(), f"{instr} {'present' if p.is_file() else 'missing'} in workspace"

    checks.append(logged_check(oracle, phase, "instructions:AEBENCH_TASK.md", instructions))
    return checks


# ----------------------------------------------------------------------------- artifact_build (§7.2)
def artifact_build_checks(oracle, config: dict) -> list:
    phase = "artifact_build"
    root = artifact_root(oracle, config)
    checks = []
    for exp in config.get("experiments", []):
        slug = exp["slug"]
        if exp.get("entrypoint"):
            def entry(e=exp) -> tuple[bool, str]:
                cands = []
                if e.get("working_dir"):
                    cands.append(root / e["working_dir"] / e["entrypoint"])
                cands.append(root / e["entrypoint"])
                for c in cands:
                    if c.exists():
                        return True, f"{c.relative_to(root).as_posix()} exists"
                return False, f"entrypoint {e['entrypoint']!r} not found"
            checks.append(logged_check(oracle, phase, f"experiment:{slug}:entrypoint", entry))
        if exp.get("check"):
            checks.append(logged_check(
                oracle, phase, f"experiment:{slug}:check",
                lambda e=exp: _run(oracle, e["check"], root, None, config.get(
                    "check_timeout_s", DEFAULT_CHECK_TIMEOUT_S))))
    return checks


# ----------------------------------------------------------------------------- benchmark_prep (§7.3)
def benchmark_prep_checks(oracle, config: dict) -> list:
    phase = "benchmark_prep"
    root = artifact_root(oracle, config)
    doc = json.loads(oracle.ref_path("datasets.json").read_text(encoding="utf-8"))
    groups: dict[str, list[dict]] = {}
    for ds in doc.get("datasets", []):
        groups.setdefault(ds["id"], []).append(ds)
    checks = []
    for did, entries in groups.items():
        def check(es=entries) -> tuple[bool, str]:
            problems, fine = [], []
            for d in es:
                p = root / d["path"]
                if not p.is_file():
                    problems.append(f"{d['path']} missing")
                elif not d.get("sha256"):
                    fine.append(f"{d['path']} exists (no sha256 declared; existence only)")
                else:
                    got = sha256_file(p)
                    if got != d["sha256"].lower():
                        problems.append(f"{d['path']} sha256 {got}, expected {d['sha256']}")
                    else:
                        fine.append(f"{d['path']} sha256 matches")
            return (False, "; ".join(problems)) if problems else (True, "; ".join(fine))
        checks.append(logged_check(oracle, phase, f"dataset:{did}", check))
    return checks


# ----------------------------------------------------------------------------- experiment_runs (§7.4)
def _excluded(rel: str, excluded: list[str]) -> bool:
    return any(rel == e or rel.startswith(e.rstrip("/") + "/") for e in excluded)


def make_scratch(workspace: Path, scratch: Path, subdir: str, excluded: list[str]) -> None:
    """Copy the workspace to `scratch`, leaving out excluded artifact-relative paths."""
    if scratch.exists():
        shutil.rmtree(scratch)
    prefix = (subdir.strip("/") + "/") if subdir else ""
    skip_abs = scratch.resolve()

    def ignore(d: str, names: list[str]) -> set[str]:
        out = set()
        for n in names:
            full = Path(d) / n
            if full.resolve() == skip_abs:
                out.add(n)
                continue
            rel = full.relative_to(workspace).as_posix()
            if prefix:
                if not rel.startswith(prefix):
                    continue
                rel = rel[len(prefix):]
            if _excluded(rel, excluded):
                out.add(n)
        return out

    shutil.copytree(workspace, scratch, symlinks=True, ignore=ignore)


def experiment_runs_checks(oracle, config: dict) -> list:
    phase = "experiment_runs"
    refs = json.loads(oracle.ref_path("reference-values.json").read_text(encoding="utf-8"))
    refs = {k: v for k, v in refs.items() if not k.startswith("_")}
    subdir = config.get("artifact_subdir") or ""
    scratch = oracle.output_path(SCRATCH_DIR)
    scratch_root = scratch / subdir if subdir else scratch
    state: dict[str, Any] = {"ready": False, "error": None, "start": None, "skipped": set()}

    def ensure_scratch() -> None:
        if state["ready"]:
            return
        state["ready"] = True
        state["start"] = time.monotonic()
        try:
            make_scratch(oracle.workspace_path(), scratch, subdir, config.get("excluded", []))
        except Exception as exc:  # noqa: BLE001
            state["error"] = f"scratch copy failed: {type(exc).__name__}: {exc}"

    budget = float(config.get("budget_s", 3600))
    checks = []
    for exp in config.get("experiments", []):
        def run(e=exp) -> tuple[bool, str]:
            ensure_scratch()
            if state["error"]:
                return False, state["error"]
            remaining = budget - (time.monotonic() - state["start"])
            expected = parse_runtime(e.get("expected_runtime"))
            if expected is not None and expected > remaining:
                state["skipped"].add(e["slug"])
                return True, "not re-executed: expected_runtime exceeds budget"
            if remaining <= 0:
                return False, "oracle time budget exhausted before this experiment ran"
            cwd = scratch_root / e["working_dir"] if e.get("working_dir") else scratch_root
            if not cwd.is_dir():
                return False, f"working_dir {e.get('working_dir')!r} missing in scratch copy"
            return _run(oracle, e["command"], cwd, e.get("env") or {}, remaining)
        checks.append(logged_check(oracle, phase, f"experiment:{exp['slug']}:run", run))

    for rid, ref in refs.items():
        def result(r=rid, spec=ref) -> tuple[bool, str]:
            ensure_scratch()
            produced_by = spec.get("produced_by")
            base = scratch_root
            owners = [produced_by] if produced_by else [e["slug"] for e in config.get("experiments", [])]
            if owners and all(o in state["skipped"] for o in owners):
                base = artifact_root(oracle, config)
            p = base / spec["output_path"]
            where = "workspace" if base != scratch_root else "re-executed scratch copy"
            if not p.is_file():
                return False, f"{spec['output_path']} not produced ({where})"
            try:
                obs = observed_values(p, spec["format"])
            except ValueError as exc:
                return False, f"{spec['output_path']}: {exc}"
            mism = compare(obs, spec["values"])
            if mism:
                more = f" (+{len(mism) - 10} more)" if len(mism) > 10 else ""
                return False, "; ".join(mism[:10]) + more
            return True, f"{len(spec['values'])} values match the reference ({where})"
        checks.append(logged_check(oracle, phase, f"result:{rid}", result))
    return checks
